export function getFoodsExcluding(exclusionIds: string[]): FoodItem[] {
  return FOODS.filter((f) => !exclusionIds.includes(f.id))
}

export function getFoodById(id: string): FoodItem | undefined {
  return FOODS.find((f) => f.id === id)
}

export function getFoodsByCategory(category: FoodItem['category'], exclusionIds: string[] = []): FoodItem[] {
  return FOODS.filter((f) => f.category === category && !exclusionIds.includes(f.id))
}

export function getFoodsByPrepTime(maxPrepTime: 'none' | 'quick' | 'medium' | 'long', exclusionIds: string[] = []): FoodItem[] {
  const order = ['none', 'quick', 'medium', 'long']
  const maxIdx = order.indexOf(maxPrepTime)
  return FOODS.filter((f) => order.indexOf(f.prep_time) <= maxIdx && !exclusionIds.includes(f.id))
}

export function getFoodsByCulture(culture: string, exclusionIds: string[] = []): FoodItem[] {
  if (culture === 'any') return getFoodsExcluding(exclusionIds)
  return FOODS.filter((f) => (f.culture === culture || f.culture === 'any' || !f.culture) && !exclusionIds.includes(f.id))
}
